mapper.select:
SELECT COALESCE(SUM(p.amount), 0)
FROM payments p
WHERE p.order_id = #{orderId}

SELECT p.id, p.order_id AS orderId, p.amount AS amount, p.received_date AS receivedDate, p.note AS note, p.created_at AS createdAt FROM payments p WHERE p.order_id IN
#{id}
ORDER BY p.received_date DESC, p.id DESC

SELECT p.id, p.order_id AS orderId, p.amount AS amount, p.received_date AS receivedDate, p.note AS note, p.created_at AS createdAt FROM payments p JOIN orders o ON p.order_id = o.id
AND o.customer_id = #{customerId}
ORDER BY p.received_date ASC, p.id ASC
